You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

Unless stated otherwise, $N = 2^n$.

\begin{definition}
 A \emph{query total search problem} is a sequence of relations $\textsc{R} = \set{R_n \subseteq \B^{n} \times O_n}$, where $O_n$ are finite sets, such that for all $x \in \B^n$ there is an $o \in O_n$ such that $(x, o) \in R_n$.
 A total search problem $\textsc{R}$ is in $\TFNP^{dt}$ if for each $o \in O_n$ there is a decision tree $T_o$ with depth $\poly(\log n)$ such that for every $x \in \B^n$, $T_o(x) = 1$ iff $(x, o) \in \textsc{R}$.
\end{definition}

In general, we use $DT(\textsc{R})$ to denote the query complexity of a search problem $\textsc{R}$.

\begin{definition}[Decision Tree Reduction]
    A \emph{decision tree reduction} from relation $R \subseteq \{0, 1\}^n \times O$ to $Q \subseteq \{0, 1\}^m \times O'$ is a set of depth-$d$ decision trees $f_i: \{0, 1\}^n \rightarrow \{0,1\}$ for each $i \in [m]$ and $g_o: \{0,1\}^n \rightarrow O$ for each $o \in O'$ such that for any $x \in \{0,1\}^n$,
    \[(x, g_o(x)) \in R  \Leftarrow (f(x), o) \in Q,\]
    where $f(x) \in \{0,1\}^m$ has $f_i(x)$ as the $i$-th bit.
    The \emph{depth} of the reduction is $d$, and the \emph{size} of the reduction is $\log m$.
    The \emph{complexity} of the reduction is $d + \log m$, and we write $Q^{dt}(R)$ to denote the minimum complexity of a decision-tree reduction from $R$ to $Q$, or $\infty$ if one does not exist.

    We extend these notations to sequences in the natural way.
   	If $R$ is a single search problem and~$\textsc{Q} = (Q_m)$ is a sequence of search problems, then we denote by $\textsc{Q}^{dt}(R)$ the minimum of $Q^{dt}_m(R)$ over all $m$.
	If $\textsc{R} = (R_n)$ is also a sequence, then we denote by $\textsc{Q}^{dt}(\textsc{R})$ the function $n\mapsto \textsc{Q}^{dt}(R_n)$. 
    A $\TFNP^{dt}$ problem $\textsc{R}$ can be \emph{black-box reduced} to $\TFNP^{dt}$ problem $\textsc{Q}$, written $\textsc{R} \leq_m \textsc{Q}$, if there is a $\poly(\log(n))$-complexity decision-tree reduction from $\textsc{R}$ to $\textsc{Q}$.
\end{definition}

In general, if a syntactic $\TFNP$ subclass $\cA$ is defined by polynomial-time black-box reductions to a complete problem $\pA$, we will use $\cA^{dt}$ to denote the class of query total search problems that can be efficiently black-box reduced to $\pA$.

\begin{restatable}{definition}{ourpigeon}\label{def:pigeon}
    For any positive integer $n$ let $t(n), M(n)$, and $N(n)$ be integer parameters satisfying $M > (t-1)N$. The $\ourPigeon{t}{M}{N}$ problem is defined as follows.

    \begin{description}
        \item[Input] $(n, h)$, where $n$ is given in unary and $h:[M] \rightarrow [N]$ is a map of $M$ pigeons to $N$ holes represented by a $\poly(n)$-size circuit.
        \item[Solutions] A \emph{$t$-collision} in $h$, which is a set of $t$ pigeons that are all assigned to the same hole by the circuit.
    \end{description}
\end{restatable}

As an important special case, we use $\tightPigeon{t}$ to indicate $\ourPigeon{t}{M}{N}$ with the tight parameter setting $M = (t-1)N+1$.

\begin{definition}[$t$-\PPP and $t$-\PWPP]\label{def:t_ppp}
    For any function $t(n) \geq 2$, define the classes
    \begin{description}
        \item[{$t$-\PPP}.] All search problems reducible to $\tightPigeon{t}$.
        \item[{$t$-\PWPP}.] All search problems reducible to $\ourPigeon{t}{M}{N}$, with $M = (t-1+c)N$ for constant $c > 0$.
    \end{description}
\end{definition}

\begin{definition}   \SAP is the set of all search problems reducible to $t(n)\text{-}\PPP$, for some $t(n)$ sub-polynomial\footnote{A function $t(n)$ is said to be sub-polynomial if $t(n) = o(n^c)$ for any $c>0$.} in $n$.
\end{definition}

Let $x_1, x_2, \ldots, x_n$ be a family of $\set{0,1}$-valued variables. 
We consider real-coefficient polynomials $p \in \RR[x_1, \dots, x_n]$ over these variables.
All polynomials that we consider are \emph{multilinear}, meaning the individual degree of any variable is at most $1$.
The algebra of multilinear polynomials is described by the quotient ring $\RR[x_1, \dots, x_n]/\langle x_i^2 - x_i\rangle_{i=1}^n$.

For any $S, T \subseteq [n]$ with $S \cap T = \emptyset$, define the polynomial \[ C_{S, T} := \prod_{i \in S} x_i \prod_{j \in T} (1-x_j). \] 
Note that for $\set{0,1}$-assignments the polynomial $C_{S, T}$ encodes the truth value of the conjunction $\bigwedge_{i \in S} x_i \land \bigwedge_{j \in T} \overline x_j$, and thus we will refer to $C_{S,T}$ as a ``conjunction'' in an abuse of notation.
If $R_n \subseteq \B^n \times O$ is a query total search problem, and $o \in O$, then a conjunction $C$ \emph{witnesses} the solution $o$ if $C(x) = 1 \Rightarrow (x,o) \in R_n$ for every $x \in \B^n$.
Similarly, we say a conjunction $C$ \emph{witnesses} $R_n$ if it witnesses some solution to $R_n$.
Each conjunction $C = C_{S,T}$ is naturally associated with a partial restriction $\rho(C) \in \set{0,1,*}$ defined by setting 
\[ \rho(C)_i = \begin{cases}
    1 & i \in S, \\
    0 & i \in T, \\
    * & \text{otherwise}.
\end{cases}\]

\begin{definition}
    \label{def:pseudoexpectation}
    Let $n \geq d$ be positive integers.
    Let $\mathcal{P}_{n,d}$ be the collection of all degree $\leq d$ multilinear polynomials over variables $x_1, \dots, x_n$.
    An operator $\psE: \mathcal{P}_{n,d} \rightarrow \RR$ is a \emph{degree-$d$ pseudoexpectation operator} if it satisfies the following three properties:
    \begin{itemize}
        \item {\bf Linearity.} $\psE$ is linear.
        \item {\bf Normalized.} $\psE[1] = 1$.
        \item {\bf Nonnegativity.} $\psE[C] \geq 0$ for all degree $\leq d$ conjunctions $C$.
    \end{itemize}
    Furthermore, if $R \subseteq \B^n \times O$ is a query total search problem, then $\psE$ is \emph{$R$-Nonwitnessing} if it additionally satisfies the following property:
    \begin{itemize}
        \item {\bf $R$-Nonwitnessing.} $\psE[C] = 0$ for any conjunction $C$ witnessing $R$.
    \end{itemize}
    If $\mathcal{F}$ is any sequence of degree $\leq d$ multilinear polynomials, then we write $\psE[\mathcal{F}] := \sum_{p \in \mathcal{F}} \psE[p]$.
\end{definition}

\begin{definition}
    Let $x_1, \ldots, x_n$ be a set of $\B$-valued variables, and let $d \leq n$.
    A \emph{degree-$d$ pseudodistribution} over these variables is a family of probability distributions \[ \mathcal{D} = \set{\mathcal{D}_S : S \subseteq [n], |S| \leq d}, \] such that the following properties hold:
    \begin{itemize}
        \item For each set $S \subseteq [n]$, $|S| \leq d$, $\mathcal{D}_S$ is supported on $\set{0,1}^S$, interpreted as boolean assignments to variables in $\set{x_i : i \in S}$.
        \item For each $S, T \subseteq [n]$, $|S|, |T| \leq d$, we have $\mathcal{D}_S^{S \cap T} = \mathcal{D}_T^{S \cap T} = \mathcal{D}_{S \cap T}$, where $\mathcal{D}_A^{B}$ for $B \subseteq A$ is the marginal distribution of variables in $B$ with respect to $\mathcal{D}_A$. 
    \end{itemize}
    \end{definition}

\begin{lemma}[\cite{Fleming19}]
    Let $\mathcal{D}$ be a degree-$d$ pseudodistribution over variables $x_1, \dots, x_n$. The operator $\psE$ defined by \[ \psE\left[\prod_{i \in S} x_i\right] = \Pr_{y \sim \mathcal{D}_S}[\forall i \in S: y_i = 1]\] and extended to all multilinear polynomials by linearity, is a degree-$d$ pseudoexpectation.
\end{lemma}

\begin{definition}[Matching Pseudodistribution]
    \label{def:matching-pseudodistribution}
    Consider $\ourPigeon{t}{M}{N}$ with $M \geq (t-1)N + 1$ pigeons and $N$ holes, and let $d \leq N/2$.
    The \emph{degree-$d$ matching pseudodistribution} for this instance is the following pseudodistribution.
    For any set of input variables $S$ in $\ourPigeon{t}{M}{N}$, let $p(S)$ denote the set of pigeons mentioned among variables in $S$.
    For each subset $S$ of variables with $|S| \leq d$, define the distribution $\mathcal{D}_S$ by sampling a uniformly random matching from the pigeons in $p(S)$ to $|p(S)|$ holes, and assigning the variables in $S$ according to this matching. Further define $\mathcal{D} = \set{\mathcal{D}_S : |S| \leq d}$ to be the collection of all such distributions.
\end{definition}

\begin{definition}
    \label{def:witnessing-family}
    Let $R \subseteq \B^n \times O$ be a query total search problem, and let $\mathcal{F}$ be a family of degree-$d$ conjunctions over input variables of $R$.
    For $t \geq 2$, the family $\mathcal{F}$ is said to be \emph{$t$-witnessing for $R$} if for any subset $\mathcal{S} \subseteq \mathcal{F}$ with $|\mathcal{S}| = t$, either $\prod_{C \in \mathcal{S}} C \equiv 0$, or $DT(R \restriction \rho) \leq d$, where $\rho$ is the concatenation of $\rho(C)$ for all $C \in \mathcal{S}$, and $D$ is some universal constant.
    In other words, either every subset of $t$ conjunctions is inconsistent, or, there is a shallow decision tree solving the restricted problem $DT(R \restriction \rho)$, where $\rho$ is the union of partial assignments corresponding to the $t$ conjunctions. We say that $\mathcal{F}$ is \emph{$t$-witnessing} if the problem $R$ is clear from context.
\end{definition}

\begin{definition}
    \label{def:collision-free}
    Let $R \subseteq \B^n \times O$ be a total query search problem, let $d, t$ be positive integers, and let $\varepsilon > 0$ be a real parameter.
    Let $\psE$ be a degree $D \geq d$ pseudoexpectation operator.
    Then $\psE$ is \emph{$(d,t,\varepsilon)$-collision-free for $R$} if it satisfies the following property:
    \begin{itemize}
        \item {\bf $t$-Collision-Freedom.} $\displaystyle \psE[\mathcal{F}] \leq \varepsilon$, for every $t$-witnessing family $\mathcal{F}$ of degree $\leq d$ conjunctions.
    \end{itemize}
\end{definition}

\begin{lemma}
    \label{lem:decision-tree-bound}
   Let $x_1, \dots, x_n$ be a set of variables, and let $t, d$ be chosen so that $(t-1)d^2 \leq n$.
   Let $\mathcal{F}$ be any family of degree $\leq d$ conjunctions over these variables, such that for every subset $\mathcal{S} \subseteq \mathcal{F}$ with $|\mathcal{S}| = t$, $\prod_{C \in \mathcal{S}} C \equiv 0$.
   If $\psE$ is a degree $D \geq (t-1)d^2$ pseudoexpectation operator, then $\psE[\mathcal{F}] \leq t-1$.
\end{lemma}

The class \UPLC is defined by its complete problem with the same name \uplc, specified in below.

\begin{definition}[\uplc]\label{def:uplc}
    A universe of elements $\B^n$ is considered.
    \begin{description}
        \item[Input] A circuit $P: \B^n \mapsto \B^{n-1}$.
        \item[Solutions] A set of $n$ distinct strings $a_1 \ldots a_n$ such that for every $j$ the strings $P(a_j), P(a_{j+1}) \ldots P(a_n)$ agree on the prefix of length $j$. 
    \end{description}
\end{definition}

\begin{lemma}
\label{lem:pwpp-uplc}
$\ourPigeon{n/2}{N}{\sqrt{N}}$ is in \UPLC.
\end{lemma}


